int licznik = 0;
int liczba = 0;

int minimum, maksimum, jasnosc;

const int segmentPins[8] = {2, 3, 4, 5, 6, 7, 8, 9};

const byte digits[10] = {
  0b00111111,
  0b00000110,
  0b01011011,
  0b01001111,
  0b01100110,
  0b01101101,
  0b01111101,
  0b00000111,
  0b01111111,
  0b01101111
};

void Znak(int iNumer) {
  byte pattern = digits[iNumer];

  for (int i = 0; i < 7; i++) {
    digitalWrite(segmentPins[i],
                 (pattern & (1 << i)) ? LOW : HIGH);
  }

  digitalWrite(9, HIGH);
}

void setup() {
  for (int i = 2; i <= 9; i++) {
    pinMode(i, OUTPUT);
  }

  pinMode(10, OUTPUT);
  pinMode(11, OUTPUT);

  delay(1000);

  minimum = analogRead(A0);
  maksimum = minimum;
}

void loop() {

  // First display
  digitalWrite(11, LOW);

  Znak(liczba % 10);

  digitalWrite(10, HIGH);
  delay(2);
  digitalWrite(10, LOW);

  // Second display
  Znak((liczba / 10) % 10);

  digitalWrite(11, HIGH);
  delay(2);

  // Read light sensor
  if (licznik++ > 100) {

    jasnosc = analogRead(A0);

    if (minimum > jasnosc)
      minimum = jasnosc;

    if (maksimum < jasnosc)
      maksimum = jasnosc;

    if (minimum != maksimum) {
      jasnosc = 99L * (jasnosc - minimum)
                / (maksimum - minimum);
    } else {
      jasnosc = 0;
    }

    liczba = constrain(jasnosc, 0, 99);

    licznik = 0;
  }
}
